/* Self-contained panel served by the RK process, without CDN dependencies. */
static const char panel[]=
"<!doctype html><html lang='zh-CN'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>RK3568 中文驾驶辅助面板</title><style>"
"*{box-sizing:border-box}body{margin:0;background:#0d1422;color:#e8edf5;font:16px system-ui,'Noto Sans CJK SC',sans-serif}"
"main{max-width:1180px;margin:auto;padding:26px}h1{font-size:27px;margin:0 0 8px}h2{font-size:18px;margin:0 0 14px}"
"p{line-height:1.7;color:#acbad0}small{color:#a6b5ca}button,select{font:inherit;border:1px solid #40516b;border-radius:8px;background:#20334d;color:#fff;padding:11px 16px;cursor:pointer;margin:4px 6px 4px 0}"
"button:hover{background:#304c70}button:focus-visible{outline:3px solid #89c4ff}.primary{background:#1761a6}.stop{background:#753a35}"
".grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{background:#172235;border:1px solid #2c3b53;border-radius:12px;padding:20px;margin:14px 0}"
".big{font-size:28px;font-weight:650;margin:10px 0}.muted{color:#a6b5ca}.badge{border:1px solid #3c587b;border-radius:20px;padding:4px 10px;font-size:13px;display:inline-block}"
".feedback{border-left:5px solid #e3ae50;min-height:110px}.alarm{border-color:#ed685d;background:#3e2229}.ok{color:#91c8ff}"
"table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid #2c3b53;padding:10px 4px}"
"#notice{color:#ffb7a9;min-height:24px}#sync{white-space:pre-line;font-size:14px;color:#b6c5d9}.events{max-height:150px;overflow:auto;font-size:14px;line-height:1.9}"
"@media(max-width:800px){.grid{grid-template-columns:1fr}main{padding:16px}.card{margin:6px 0}button{padding:10px 12px}}"
"</style><main><h1>中文驾驶辅助面板 <span class='badge'>RK3568 · 第六版</span></h1>"
"<p>前方 HDMI：车道、车辆、行人、灯色；左侧 OV5640、右侧以太网：车辆辅助观察。</p>"
"<div class='card'><button class='primary' onclick=\"act('start')\">开始检测 / 从头重播</button><button class='stop' onclick=\"act('stop')\">停止检测</button>"
"<span id='connection' class='badge'>连接中</span><div id='notice' role='alert'></div><div id='sync'>等待状态</div></div>"
"<div class='grid'><section class='card'><h2>前方车道边界</h2><div id='lines' class='big'>等待识别</div><div id='laneAge' class='muted'>—</div></section>"
"<section class='card'><h2>交通灯色</h2><div id='signal' class='big'>待确认</div><small>仅显示灯色；未关联本车道及箭头方向，不能据此判断可左转或右转。</small></section>"
"<section class='card'><h2>模拟车辆状态 <span class='badge'>模拟</span></h2><div id='speed' class='big'>0 km/h · P挡</div>"
"<button onclick=\"drive('slower')\">−5</button><button onclick=\"drive('faster')\">+5</button><button onclick=\"drive('brake')\">模拟制动</button>"
"<div>模拟挡位 <select id='gear' aria-label='模拟挡位' onchange='shift(this.value)'><option>P</option><option>N</option><option>D</option><option>R</option></select></div>"
"<small>与视频播放速度及真实车辆无关；停车后换挡，倒挡最高10 km/h。</small></section></div>"
"<section class='card'><h2>变道请求</h2><button class='primary' onclick=\"drive('left')\">请求向左变道</button><button class='primary' onclick=\"drive('right')\">请求向右变道</button>"
"<button onclick=\"drive('cancel')\">取消请求</button><span id='turn' class='badge'>转向意图：无</span>"
"<div id='feedback' class='card feedback' aria-live='polite'><strong id='verdict'>等待请求</strong><p id='explain'>请求后将结合所选侧边界和侧方证据持续反馈，10秒后请求自动结束。</p></div>"
"<small>本轮未做侧方区域标定。侧方有车辆不直接等于冲突，未检测到车辆也不代表安全；面板给出辅助提示，不执行车辆控制。</small></section>"
"<section class='card'><h2>三路感知与数据时效</h2><table><thead><tr><th>输入</th><th>检测状态</th><th>车辆数</th><th>结果年龄</th><th>时间关联</th></tr></thead><tbody id='sources'></tbody></table>"
"<p id='people'>前方行人：待确认</p><small>行人检测用于展示；本版没有行人冲突区域，不因检测到行人直接报警。结果超过750ms会失效。</small></section>"
"<section class='card'><h2>最近请求反馈</h2><div id='events' class='events'>尚无记录</div></section></main>"
"<script>const $=id=>document.getElementById(id);let currentSession=null,lastEvent='',eventRows=[];"
"const states={IDLE:'等待开始',PREPARING:'视频源回到起点',WAIT_READY:'等待两路首帧到达板端',STARTING:'下发共同播放指令',WAIT_FRAMES:'等待播放画面配对',RUNNING:'检测中：两路配对正常',SYNC_LOST:'同步丢失：暂停联合判断',ENDED:'录像结束',STOPPING:'正在停止',STOPPED:'已停止',ERROR:'故障：检查中继和视频源'};"
"const reasons={waiting_start:'等待开始',waiting_source_prepare:'等待视频源准备',waiting_received_ready_pair_open_preview:'等待首帧，请保持三路预览开启',waiting_source_play:'等待视频源开始播放',waiting_received_playing_pair:'等待播放帧配对',received_matching_source_pair:'已收到匹配画面',no_fresh_matching_pair:'超过1秒没有新配对',source_playback_held_or_ended:'视频暂停或结束',user_stopped:'用户停止',source_command_failed_check_relay:'视频源指令失败，请检查中继',timeout_check_source_relay_and_preview:'超时，请检查视频源、中继和预览',controller_shutdown:'服务退出'};"
"const feedback={IDLE:['等待请求','请选择向左或向右变道。'],CANCELLED:['请求已取消','转向意图已清除。'],EXPIRED:['请求已结束','10秒观察时间已到，可重新发出请求。'],NOT_RUNNING:['当前无法判断','请先开始检测并确认视频配对正常。'],LANE_STALE:['暂缓变道：车道结果失效','缺少750ms内的有效车道结果，请继续观察。'],SOLID_BLOCK:['禁止跨越实线变道','所选一侧为实线，已触发实线变道报警；请保持当前车道。'],LINE_UNKNOWN:['暂缓变道：边界待确认','当前无法确认所选一侧为虚线。'],SIDE_STALE:['边界为虚线，侧方证据不足','侧方结果缺失或已过期，请检查侧方视频。'],LEFT_VEHICLE_MANUAL:['左侧检测到车辆，请人工观察','边界为虚线；OV5640同步未确认、区域未标定，不能自动判断是否冲突。'],LEFT_MANUAL:['左侧需人工确认','边界为虚线；未检测到车辆，但OV5640同步未确认、区域未标定。'],SIDE_TIME_MISMATCH:['右侧结果时间不匹配','边界为虚线；右侧识别对应画面与当前前方相差超过250ms。'],SIDE_VEHICLE_REVIEW:['右侧检测到车辆，请观察','边界为虚线；区域尚未标定，无法判断是否占用目标车道。'],DASHED_REVIEW:['边界为虚线，请确认右侧环境','右侧有效结果中未检测到车辆；区域未标定，仍需人工观察。']};"
"async function post(path){const r=await fetch(path,{method:'POST',headers:{'X-Sync-Control':'1'}});const j=await r.json();if(!r.ok)throw Error(j.error||'操作失败');return j}"
"async function act(a){try{$('notice').textContent='';await post('/api/'+a);await tick(false)}catch(e){$('notice').textContent=e.message}}"
"async function drive(a){try{$('notice').textContent='';await post('/api/drive?action='+encodeURIComponent(a));await tick(false)}catch(e){$('notice').textContent=e.message}}"
"async function shift(g){await drive(g)}const age=x=>x<0?'无结果':x+' ms';"
"function render(s){const d=s.drive;if(!d)throw Error('当前服务尚未更新到驾驶面板版本');$('connection').textContent='板端已连接';"
"if(currentSession!==s.session){currentSession=s.session;eventRows=[];lastEvent='';$('events').textContent='尚无记录'}"
"$('sync').textContent=(states[s.state]||s.state)+' · '+(reasons[s.reason]||s.reason)+'\\n播放编号 '+s.session+' · 配对 '+s.wire+' · 配对年龄 '+age(s.pair_age_ms)+' · 前方 '+s.front_ms+'ms / 右侧 '+s.right_ms+'ms';"
"const ln=['待确认','实线','虚线'];$('lines').textContent='左 '+ln[d.line[0]]+' · 右 '+ln[d.line[1]];$('laneAge').textContent='车道结果年龄：'+age(d.lane_age_ms);"
"$('signal').textContent=['待确认','红灯','黄灯','绿灯'][d.signal];$('signal').style.color=['#afbed1','#ff8a80','#ffd478','#7fe1b1'][d.signal];"
"$('speed').textContent=d.speed_kmh+' km/h · '+d.gear+'挡';$('gear').value=d.gear;$('turn').textContent='转向意图：'+['无','左','右'][d.request];"
"const f=feedback[d.feedback]||['待确认',d.feedback];$('verdict').textContent=f[0];$('explain').textContent=f[1];$('feedback').className='card feedback'+(d.solid_alarm?' alarm':'');"
"$('sources').replaceChildren();['前方 HDMI','左侧 OV5640','右侧以太网'].forEach((name,i)=>{const tr=document.createElement('tr');[name,d.object_valid[i]?'识别有效':'等待 / 过期',d.object_valid[i]?String(d.vehicles[i]):'—',age(d.object_age_ms[i]),i===1?'手动对齐，未确认':i===2?'结果源时间差 '+d.scene_delta_ms+'ms':'前方主视角'].forEach(t=>{let td=document.createElement('td');td.textContent=t;tr.appendChild(td)});$('sources').appendChild(tr)});"
"$('people').textContent='前方行人：'+(d.object_valid[0]?d.people+' 人（仅展示）':'待确认');"
"const key=d.request_id+':'+d.feedback;if(d.request_id&&key!==lastEvent){lastEvent=key;eventRows.unshift(new Date().toLocaleTimeString()+' · 请求'+d.request_id+' · '+f[0]);eventRows=eventRows.slice(0,12);$('events').replaceChildren(...eventRows.map(t=>{let el=document.createElement('div');el.textContent=t;return el}))}}"
"async function tick(schedule=true){try{render(await(await fetch('/api/status',{cache:'no-store'})).json())}catch(e){$('connection').textContent='连接中断';$('verdict').textContent='板端状态不可用';$('explain').textContent='暂停依据旧结果判断，请检查控制服务。';$('lines').textContent='待确认';$('signal').textContent='待确认';$('sources').textContent='数据已失效';$('turn').textContent='转向意图：待确认';$('speed').textContent='模拟状态待确认';$('feedback').className='card feedback'}if(schedule)setTimeout(tick,300)}tick();"
"</script></html>";
